[planner] {
  "plan": {
    "objective": "Produce a benchmark-ready long-horizon experiment plan",
    "horizon": "long-term (multi-phase, iterative, ≥5 steps)",
    "core_components": [
      "tool_use",
      "evidence_collection",
      "delegation",
      "synthesis",
      "risk_tracking"
    ],
    "phases": [
      {
        "phase": "1. Clarify & Scope",
        "activities": [
          "Confirm benchmark criteria (e.g., GAIA, RULER, or custom metrics)",
          "Define success signals for each core component",
          "Establish timeline, milestones, and handoff protocols"
        ]
      },
      {
        "phase": "2. Tool Integration Design",
        "activities": [
          "Select and validate tools per function: e.g., local_lookup for evidence, plan_outline for scaffolding",
          "Define input/output contracts and error-handling policies",
          "Embed tool-use logging for reproducibility and audit"
        ]
      },
      {
        "phase": "3. Evidence Collection Protocol",
        "activities": [
          "Run deterministic local lookups across key dimensions (e.g., 'tool use', 'risk tracking')",
          "Tag evidence by source, timestamp, and relevance score",
          "Store artifacts in shared workspace with versioned URIs"
        ]
      },
      {
        "phase": "4. Delegation Framework",
        "activities": [
          "Assign subtasks using matriarchal_elephant topology",
          "Enforce handoff_policy = 'summary_plus_artifacts'",
          "Track delegation depth and agent capability alignment"
        ]
      },
      {
        "phase": "5. Synthesis Engine",
        "activities": [
          "Aggregate evidence and delegated outputs into unified narrative",
          "Cross-validate claims against original benchmarks",
          "Generate structured output: JSON + human-readable summary"
        ]
      },
      {
        "phase": "6. Risk Tracking & Adaptation",
        "activities": [
          "Log risks per phase (e.g., tool failure, evidence gaps, delegation latency)",
          "Assign severity, owner, and mitigation status",
          "Trigger adaptive replanning if ≥2 high-severity risks accumulate"
        ]
      }
    ],
    "benchmark_readiness_checks": [
      "All phases include measurable exit criteria",
      "Evidence is traceable to deterministic lookup results",
      "Delegation adheres to handoff and shared_workspace policies",
      "Synthesis output conforms to artifact-first structure",
      "Risk log is machine-parsable and updated per phase"
    ]
  }
}

[reviewer] {
  "plan": {
    "horizon": "long",
    "benchmark_readiness": true,
    "components": {
      "tool_use": {
        "strategy": "Tool-augmented iterative refinement",
        "tools": ["plan_outline", "local_lookup"],
        "validation": "Each tool call must return structured, deterministic output; unused tools are logged and justified."
      },
      "evidence_collection": {
        "sources": ["local_lookup (domain-specific experimental patterns)", "plan_outline (scaffolded structure)"],
        "criteria": "Evidence must be deterministic, reproducible, and tagged with provenance (tool + query)."
      },
      "delegation": {
        "policy": "summary_plus_artifacts",
        "handoff_protocol": "Subtasks delegated only when >2 distinct evidence types required; all artifacts retained in shared workspace.",
        "topology": "matriarchal_elephant"
      },
      "synthesis": {
        "method": "Structured aggregation: map evidence → plan steps → cross-validate against benchmark criteria (reproducibility, traceability, modularity).",
        "output_format": "JSON with explicit fields for each component and audit trail of tool use."
      },
      "risk_tracking": {
        "categories": ["tool failure", "evidence gap", "delegation drift", "synthesis ambiguity"],
        "mitigation": ["fallback to local_lookup if plan_outline returns incomplete steps", "evidence gap triggers re-query with expanded scope", "all delegations logged with timestamp, agent ID, and artifact hash"]
      }
    }
  }
}
